# certify the 554 completion rules: each must lie in the K-span of the certified rules G0 and of the overlap
# polynomials of G0 (reduced by G0), all of which lie in the ideal generated by G0, hence in I_K.
import pickle, sys, time
from collections import defaultdict
from functools import lru_cache
sys.path.insert(0,'/home/claude/hj/work/Calculs/zhu-exact')
import kfast as KF
t0=time.time()
def log(*a): print(*a,'%.0fs'%(time.time()-t0),flush=True)
ZE='/home/claude/hj/work/Calculs/zhu-exact'
U=pickle.load(open(ZE+'/upper_exact.pkl','rb'))
AR=pickle.load(open(ZE+'/upper_exact.pkl','rb'))  # placeholder, replaced below
G=pickle.load(open('/home/claude/hj/work/verif/membership/G0.pkl','rb'))['G0']
import pickle as pk
D=pk.load(open(ZE+'/rows_exact.pkl','rb')); AR=D['ARROWS']; del D
RULES=U['rules']; G0={q:RULES[q] for q in G}; NEW=[q for q in RULES if q not in G0]
s_=lambda a:AR[a]['source']; t_=lambda a:AR[a]['target']
log('G0',len(G0),'new',len(NEW))
def add(o,row,c):
    for p,v in row.items():
        z=KF.add(o.get(p,KF.ZERO),KF.mul(c,v))
        if KF.iszero(z): o.pop(p,None)
        else: o[p]=z
@lru_cache(None)
def nf(p):          # reduction by G0, rightmost occurrence first (own strategy)
    for i in range(len(p)-2,-1,-1):
        q=p[i:i+2]
        if q in G0:
            o={}
            for w,c in G0[q].items(): add(o,nf(p[:i]+w+p[i+2:]),c)
            return o
    return {p:KF.ONE}
needed={(t_(q[0]),s_(q[-1])) for q in NEW}
first=defaultdict(list)
for q in G0: first[q[0]].append(q)
byT=defaultdict(list)
for q in G0: byT[t_(q[0])].append(q)
def key(p): return (-len(p),p)
ok=0; bad=[]; nov=0
for n,ep in enumerate(sorted(needed)):
    rows=[]
    for q,r in G0.items():
        if (t_(q[0]),s_(q[-1]))==ep:
            v={q:KF.ONE}
            for w,c in r.items(): add(v,{w:KF.ONE},KF.neg(c))
            rows.append(v)
    for q1 in byT[ep[0]]:
        for q2 in first[q1[1]]:
            if s_(q2[1])!=ep[1]: continue
            nov+=1
            v={}
            for x,c in G0[q1].items(): add(v,nf(x+(q2[1],)),c)
            for x,c in G0[q2].items(): add(v,nf((q1[0],)+x),KF.neg(c))
            if v: rows.append(v)
    tab={}
    for v in rows:
        while v:
            lead=min(v,key=key)
            if lead not in tab: break
            add(v,tab[lead],KF.neg(v[lead]))
        if v:
            iv=KF.inv(v[lead]); tab[lead]={p:KF.mul(x,iv) for p,x in v.items()}
    del rows
    for q in NEW:
        if (t_(q[0]),s_(q[-1]))!=ep: continue
        v={q:KF.ONE}
        for w,c in RULES[q].items(): add(v,{w:KF.ONE},KF.neg(c))
        while v:
            lead=min(v,key=key)
            if lead not in tab: break
            add(v,tab[lead],KF.neg(v[lead]))
        if v: bad.append(q)
        else: ok+=1
    del tab
    if n%10==0:
        nf.cache_clear(); log('ep',n,'of',len(needed),'overlaps so far',nov,'certified',ok,'failures',len(bad))
log('completion rules certified (reduce to 0 modulo span of G0 and its reduced overlaps):',ok,'of',len(NEW),'failures',len(bad),'overlaps used',nov)
